const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const blueLagoon = ee.Geometry.Point([-22.45, 63.88]);
  const reykjavik = ee.Geometry.Point([-21.95, 64.15]);

  const startDate = '2024-11-01';
  const endDate = '2024-11-30';

  // 2. Data Acquisition & Check
  // VIIRS DNB monthly composite (most reliable for nighttime lights)
  let collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(startDate, endDate);

  const collectionSize = await collection.size().getInfo();
  console.log(`Collection size: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No VIIRS data available for November 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get the image for November 2024
  const image = collection.first();
  const band = 'avg_rad'; // Average radiance band

  // Buffer points slightly to get representative area
  const blueLagoonArea = blueLagoon.buffer(500);
  const reykjavikArea = reykjavik.buffer(500);

  // 4. Calculation - Get brightness for both locations
  const blueLagoonStats = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blueLagoonArea,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const reykjavikStats = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: reykjavikArea,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  // Get pixel counts to check for C2
  const blueLagoonCount = await image.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: blueLagoonArea,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const reykjavikCount = await image.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reykjavikArea,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const blPixels = blueLagoonCount[band];
  const rvkPixels = reykjavikCount[band];

  console.log(`Blue Lagoon pixels: ${blPixels}, Reykjavik pixels: ${rvkPixels}`);

  if (blPixels === 0 || rvkPixels === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  const blueLagoonBrightness = blueLagoonStats[band];
  const reykjavikBrightness = reykjavikStats[band];

  // 5. Validation & Final Answer
  console.log(`Blue Lagoon brightness: ${blueLagoonBrightness}`);
  console.log(`Reykjavik brightness: ${reykjavikBrightness}`);

  if (blueLagoonBrightness === null || blueLagoonBrightness === undefined || 
      reykjavikBrightness === null || reykjavikBrightness === undefined ||
      isNaN(blueLagoonBrightness) || isNaN(reykjavikBrightness)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (blueLagoonBrightness > reykjavikBrightness) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
